source='''from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    candidates = []
    for r, row in enumerate(grid):
        cells = [c for c, value in enumerate(row) if value != background]
        if not cells:
            continue
        lo, hi = cells[0], cells[-1]
        color = row[lo]
        if all(row[c] == color for c in range(lo, hi + 1)):
            candidates.append((r, lo, hi, color))
    if len(candidates) < 2:
        return out
    max_length = max(hi - lo + 1 for _, lo, hi, _ in candidates)
    for r, lo, hi, color in candidates:
        length = hi - lo + 1
        if length < max_length:
            end = min(len(grid[0]), lo + max_length)
            for c in range(hi + 1, end):
                out[r][c] = 1
    return out
'''
